# Generated by Claudian.
"""Cancellable, language-aware speech synthesis.

Two requirements shape everything here:

  INTERRUPTIBLE  Synthesis must stop within a few tens of milliseconds of the
                 user speaking. A `subprocess.run()` that blocks until the
                 sentence finishes cannot do that, so playback is driven in
                 chunks with a stop check between each one.

  CORRECT VOICE  macOS has a voice per locale. Reading Tamil with an American
                 English voice produces something genuinely worse than
                 silence, so a missing voice is reported rather than
                 substituted.

Sentence-splitting is what makes it feel fast: the first sentence starts
playing while the rest is still being prepared, so perceived latency is
the time to the first clause rather than to the whole paragraph.
"""

from __future__ import annotations

import re
import subprocess
import threading
from dataclasses import dataclass
from typing import Callable, Iterator, Optional

from .languages import DEFAULT, Language, voice_for

StopCheck = Callable[[], bool]
# Split on sentence ends, including the Devanagari danda and CJK full stop,
# or Hindi and Japanese would each arrive as one long unsplittable block.
_SENTENCE = re.compile(r"(?<=[.!?।。])\s+")


def split_sentences(text: str, min_len: int = 15,
                    tail_min: int = 8) -> list[str]:
    """Chunks big enough to sound natural, small enough to abort quickly.

    The tail rule matters more than it looks. Merging any leftover into the
    previous chunk unconditionally meant "Hello. How are you? I am well."
    came back as ONE chunk — the whole reply synthesised as a single
    uninterruptible block, which defeats both streaming and barge-in. Only a
    genuine fragment (shorter than `tail_min`) gets merged now; anything that
    reads as a sentence stands alone.
    """
    parts: list[str] = []
    buf = ""

    for piece in _SENTENCE.split(text.strip()):
        piece = piece.strip()
        if not piece:
            continue
        buf = f"{buf} {piece}".strip() if buf else piece
        # Flushing every clause makes speech choppy; flushing too rarely makes
        # interruption feel laggy.
        if len(buf) >= min_len:
            parts.append(buf)
            buf = ""

    if buf:
        if parts and len(buf) < tail_min:
            parts[-1] = f"{parts[-1]} {buf}".strip()
        else:
            parts.append(buf)
    return parts


@dataclass
class SpeakResult:
    completed: bool          # False if interrupted
    spoken: str              # what was actually said before stopping
    remaining: str           # what was not
    voice: Optional[str]
    note: Optional[str] = None


class MacSayTTS:
    """macOS `say`, driven per sentence so it can be cut off.

    `say` has no streaming API, but it does exit when killed. Running one
    process per sentence and terminating it on interrupt gives a worst-case
    latency of one sentence rather than one paragraph.
    """

    name = "say"

    def __init__(self, rate: int = 180):
        self.rate = rate
        self._proc: Optional[subprocess.Popen] = None
        self._lock = threading.Lock()

    def speak(
        self,
        text: str,
        lang: Language = DEFAULT,
        should_stop: Optional[StopCheck] = None,
        on_sentence: Optional[Callable[[str], None]] = None,
    ) -> SpeakResult:
        voice = voice_for(lang)
        sentences = split_sentences(text)
        spoken: list[str] = []

        for i, sentence in enumerate(sentences):
            if should_stop and should_stop():
                return SpeakResult(False, " ".join(spoken),
                                   " ".join(sentences[i:]), voice)

            cmd = ["say", "-r", str(self.rate)]
            if voice:
                cmd += ["-v", voice]
            cmd.append(sentence)

            with self._lock:
                self._proc = subprocess.Popen(
                    cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

            # Poll rather than wait(): wait() cannot be interrupted, and the
            # whole design depends on noticing a barge-in mid-sentence.
            while True:
                try:
                    if self._proc.poll() is not None:
                        break
                except Exception:
                    break
                if should_stop and should_stop():
                    self.stop()
                    return SpeakResult(False, " ".join(spoken),
                                       " ".join(sentences[i:]), voice)
                threading.Event().wait(0.03)   # 30ms — inaudible, responsive

            spoken.append(sentence)
            if on_sentence:
                on_sentence(sentence)

        with self._lock:
            self._proc = None

        note = None
        if voice is None and lang.code != "en":
            from .languages import missing_voice_note
            note = missing_voice_note(lang)

        return SpeakResult(True, text, "", voice, note)

    def stop(self) -> None:
        with self._lock:
            proc, self._proc = self._proc, None
        if proc and proc.poll() is None:
            try:
                proc.terminate()
                proc.wait(timeout=0.4)
            except Exception:
                try:
                    proc.kill()
                except Exception:
                    pass


class ElevenLabsTTS:
    """Streaming neural TTS, reusing the project's existing engine.

    That engine already streams PCM chunks and polls a stop callback between
    them, which is exactly the contract needed here — so this adapts it rather
    than reimplementing HTTP streaming.
    """

    name = "elevenlabs"

    def __init__(self):
        self._engine = None

    @property
    def available(self) -> bool:
        try:
            from config import settings
            return bool(settings.ELEVENLABS_API_KEY and settings.ELEVENLABS_VOICE_ID)
        except Exception:
            return False

    def _get(self):
        if self._engine is None:
            from voice.speech_engines import build_engine
            self._engine = build_engine()
        return self._engine

    def speak(
        self,
        text: str,
        lang: Language = DEFAULT,
        should_stop: Optional[StopCheck] = None,
        on_sentence: Optional[Callable[[str], None]] = None,
    ) -> SpeakResult:
        engine = self._get()
        sentences = split_sentences(text)
        spoken: list[str] = []

        for i, sentence in enumerate(sentences):
            # Early return (interrupted mid-sentence): preserve the engine name
            # so callers that inspect `result.voice` get a consistent value.
            if should_stop and should_stop():
                return SpeakResult(False, " ".join(spoken),
                                   " ".join(sentences[i:]), self.name)
            ok = engine.speak(sentence, should_stop=should_stop)
            if not ok:
                return SpeakResult(False, " ".join(spoken),
                                   " ".join(sentences[i:]), self.name)
            spoken.append(sentence)
            if on_sentence:
                on_sentence(sentence)

        return SpeakResult(True, text, "", self.name)

    def stop(self) -> None:
        if self._engine is not None:
            try:
                self._engine.stop()
            except Exception:
                pass


class TextToSpeech:
    """Picks an engine per language.

    ElevenLabs sounds better but is one voice: using it for Tamil means Tamil
    read with an English mouth. macOS has real per-language voices, so
    non-English goes there whenever a voice exists.
    """

    def __init__(self, prefer_neural: bool = True):
        self.mac = MacSayTTS()
        self.neural = ElevenLabsTTS()
        self.prefer_neural = prefer_neural

    def _engine_for(self, lang: Language):
        if lang.code == "en" and self.prefer_neural and self.neural.available:
            return self.neural
        return self.mac

    def speak(self, text: str, lang: Language = DEFAULT,
              should_stop: Optional[StopCheck] = None,
              on_sentence: Optional[Callable[[str], None]] = None) -> SpeakResult:
        if not text or not text.strip():
            return SpeakResult(True, "", "", None)
        return self._engine_for(lang).speak(text, lang, should_stop, on_sentence)

    def stop(self) -> None:
        self.mac.stop()
        self.neural.stop()

    def can_speak(self, lang: Language) -> bool:
        return lang.code == "en" or voice_for(lang) is not None